INSERT INTO "refills" ("id", "category_id", "name", "description", "image", "is_active", "created_at", "updated_at") VALUES
('0296871c-441e-4d6d-87e9-f3e2a45655a1',	'3ab2c529-3a4a-4e6b-9289-30bc9e1cd31f',	'Garena Free Fire',	'Free Fire é um jogo eletrônico mobile de ação-aventura do gênero battle royale, criado pela desenvolvedora vietnamita 111dots Studio e publicado pela Garena. O jogo obteve um beta aberto em novembro de 2017 e foi lançado oficialmente para Android de iOS em 4 de dezembro de 2017. ',	'uploads/t6gejvv09g22ghc6sgk79d6p.jpg',	'1',	'2026-01-03 10:03:15.535+00',	'2026-01-03 10:38:02.501+00'),
('420779f0-cc35-473a-ba35-f0d1e69f91b3',	'3ab2c529-3a4a-4e6b-9289-30bc9e1cd31f',	'Delta Force',	'Delta Force é um jogo eletrônico de tiro tático em primeira pessoa gratuito para Microsoft Windows, Android e iOS. Faz parte da série Delta Force, anteriormente desenvolvida e publicada pela NovaLogic.',	'uploads/mbj732a2wan08ozp2xqxepvp.jpg',	'1',	'2026-01-03 19:12:37.11+00',	'2026-01-03 19:12:37.11+00'),
('1007fc24-553d-4a3f-8c8e-84727f8a7f01',	'60ecfd0d-7ca7-47e9-aef1-32d7ad3b53d4',	'Netflix',	'A Netflix é um serviço americano de streaming de vídeo sob demanda por assinatura. O serviço distribui principalmente filmes e programas de televisão originais e adquiridos de vários gêneros e está disponível internacionalmente em vários idiomas.',	'uploads/rz70tjo2wdkutje42uzpxgxs.png',	'1',	'2026-01-03 19:22:22.942+00',	'2026-01-03 19:22:22.942+00'),
('96e409d4-5097-49a9-8101-82748b631221',	'4abf958a-6cd6-467d-ac2b-24c0819c9a8b',	'CapCut ',	'CapCut é um aplicativo de edição de vídeos curtos desenvolvido pela ByteDance. Também é conhecido como JianYing na China e ViaMaker internacionalmente. O aplicativo foi lançado pela primeira vez na China em 2019 e estava inicialmente disponível para iPhone e Android.
